, "multiline": false}, {"key": "scheduled", "label": "When Will You Do It?", "placeholder": "Day and time (be specific)...", "multiline": false}, {"key": "predicted_mood", "label": "Predicted Mood After (0–10)", "placeholder": "How do you think you will feel?", "multiline": false}]}, {"id": 3, "title": "Cognitive Distortions", "subtitle": "Identify Thinking Traps", "category": "CBT", "icon": "🔍", "color": "#7C3AED", "duration": "5–10 min", "type": "checklist", "description": "Recognize common cognitive distortions in your thinking. Check any that applied today.", "checklistItems": ["🔮 All-or-Nothing Thinking — Seeing things in black and white, no middle ground", "🌩️ Catastrophizing — Expecting the worst possible outcome", "🎭 Mind Reading — Assuming you know what others are thinking", "🔭 Fortune Telling — Predicting negative outcomes as if they are facts", "🧲 Mental Filter — Dwelling only on the negatives, ignoring the positives", "🚫 Disqualifying the Positive — Dismissing good things as \"not counting\"", "💭 Should Statements — Rigid rules about how you or others \"should\" be", "🏷️ Labeling — Attaching a global negative label (\"I'm a failure\")", "🔍 Magnification — Exaggerating the importance of problems", "💔 Emotional Reasoning — \"I feel it, therefore it must be true\"", "🏋️ Personalization — Blaming yourself for things outside your control", "🌀 Overgeneralization — Drawing broad conclusions from one event"]}, {"id": 4, "title": "Problem Solving", "subtitle": "Structured Steps", "category": "CBT", "icon": "🧩", "color": "#E8673A", "duration": "15–20 min", "type": "worksheet", "description": "Break down a problem into manageable steps and generate practical solutions.", "worksheetFields": [{"key": "problem", "label": "Define the Problem", "placeholder": "Describe the problem as specifically as possible...", "multiline": true}, {"key": "goal", "label": "What Would a Solution Look Like?", "placeholder": "Describe your ideal outcome...", "multiline": true}, {"key": "